// Parse and validate sub-agent execution request
const payload = $json;

// Validate required fields
if (!payload.agent_config || !payload.prompt || !payload.assignment) {
    return [{ json: { error: 'Invalid sub-agent request structure' } }];
}

const agent = payload.agent_config;
const assignment = payload.assignment;

// Prepare Claude API request
const claudeRequest = {
    model: 'claude-3-5-sonnet-20241022',
    max_tokens: agent.max_tokens || 4000,
    temperature: agent.temperature || 0.7,
    messages: [
        {
            role: 'user',
            content: payload.prompt
        }
    ],
    metadata: {
        agent_id: agent.agent_id,
        agent_role: agent.role,
        agent_name: agent.name,
        task_id: assignment.task_id,
        session_id: payload.session_context?.session_id,
        execution_timestamp: payload.timestamp
    }
};

// Add system message if available
if (agent.prompt_template && agent.prompt_template.includes('You are')) {
    const systemMessage = agent.prompt_template.split('\n\n')[0];
    claudeRequest.messages.unshift({
        role: 'system',
        content: systemMessage
    });
}

return [{
    json: {
        claudeRequest,
        agentConfig: agent,
        assignment: assignment,
        sessionContext: payload.session_context,
        originalPayload: payload
    }
}];

// Process Claude response and format for sub-agent system
const claudeResponse = $json;
const originalData = $('Prepare Claude Request').first().json;
const agentConfig = originalData.agentConfig;
const assignment = originalData.assignment;

// Extract response content
let responseContent = '';
if (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) {
    responseContent = claudeResponse.content[0].text;
} else if (claudeResponse.text) {
    responseContent = claudeResponse.text;
} else {
    responseContent = 'No response content received';
}

// Calculate usage and cost
const usage = claudeResponse.usage || {};
const inputTokens = usage.input_tokens || 0;
const outputTokens = usage.output_tokens || 0;
const totalTokens = inputTokens + outputTokens;

// Estimate cost (Claude 3.5 Sonnet pricing)
const costPerInputToken = 0.000003;
const costPerOutputToken = 0.000015;
const estimatedCost = (inputTokens * costPerInputToken) + (outputTokens * costPerOutputToken);

// Quality assessment
const qualityMetrics = {
    response_length: responseContent.length,
    token_usage: {
        input: inputTokens,
        output: outputTokens,
        total: totalTokens
    },
    estimated_cost: estimatedCost,
    response_quality: {
        has_structure: responseContent.includes('1.') || responseContent.includes('##'),
        has_recommendations: responseContent.toLowerCase().includes('recommend') || responseContent.toLowerCase().includes('suggest'),
        has_analysis: responseContent.toLowerCase().includes('analyze') || responseContent.toLowerCase().includes('assessment'),
        completeness_score: Math.min(1.0, responseContent.length / 1000) // Simple completeness metric
    }
};

// Create structured response
const subAgentResponse = {
    success: true,
    agent_id: agentConfig.agent_id,
    agent_name: agentConfig.name,
    agent_role: agentConfig.role,
    task_id: assignment.task_id,
    session_id: originalData.sessionContext?.session_id,

    // Claude response
    content: responseContent,
    model: claudeResponse.model || 'claude-3-5-sonnet-20241022',

    // Usage and cost analytics
    analytics: {
        usage: usage,
        cost_analysis: {
            estimated_cost: estimatedCost,
            cost_breakdown: {
                input_cost: inputTokens * costPerInputToken,
                output_cost: outputTokens * costPerOutputToken
            },
            efficiency_score: totalTokens > 0 ? Math.min(1.0, responseContent.length / totalTokens) : 0
        },
        quality_metrics: qualityMetrics.response_quality
    },

    // Task metadata
    task_metadata: {
        task_description: assignment.task_description,
        task_context: assignment.context,
        priority: assignment.priority,
        completion_time: new Date().toISOString()
    },

    // Agent metadata
    agent_metadata: {
        capabilities: agentConfig.capabilities,
        specialization: agentConfig.role,
        execution_time: new Date().toISOString(),
        prompt_template_used: agentConfig.prompt_template ? true : false
    },

    // System metadata
    system_metadata: {
        n8n_workflow: 'Claude Sub-Agent Execution',
        integration_version: '1.0.0',
        execution_mode: 'sub_agent',
        collaboration_ready: true
    }
};

return [subAgentResponse];

// Store collaboration result in memory/database
const response = $json;
const originalData = $('Prepare Claude Request').first().json;

// Create collaboration record
const collaborationRecord = {
    record_id: `collab_${Date.now()}`,
    timestamp: new Date().toISOString(),

    // Agent execution details
    agent_execution: {
        agent_id: response.agent_id,
        agent_name: response.agent_name,
        agent_role: response.agent_role,
        task_id: response.task_id,
        session_id: response.session_id
    },

    // Results and analytics
    results: {
        content: response.content,
        analytics: response.analytics,
        quality_metrics: response.analytics.quality_metrics
    },

    // Context and metadata
    context: {
        task_description: response.task_metadata.task_description,
        task_context: response.task_metadata.task_context,
        session_context: originalData.sessionContext
    },

    // System tracking
    system_info: {
        workflow_version: '1.0.0',
        execution_successful: response.success,
        collaboration_ready: response.system_metadata.collaboration_ready
    }
};

// Log the collaboration (in production, this would go to a database)
console.log('Sub-Agent Collaboration Record:', JSON.stringify(collaborationRecord, null, 2));

return [{
    json: {
        collaboration_record: collaborationRecord,
        sub_agent_response: response,
        storage_success: true,
        timestamp: new Date().toISOString()
    }
}];
